package net.civeira.phylax.feature.oauth.userinvitation.application;

import net.civeira.phylax.common.security.Actor;

/**
 * Who may create, cancel and resend invitations of a tenant (task 2.2): an authenticated
 * {@code admin} of that tenant, or a root administrator ({@code platform:global_access}), as for
 * the rest of the user administration.
 */
public final class InvitationAdminPolicy {

  private InvitationAdminPolicy() {}

  /**
   * Whether the actor manages the invitations of a tenant.
   *
   * @param actor caller
   * @param tenantUid uid of the tenant of the route
   * @param tenantName name of the tenant of the route
   * @return true when allowed
   */
  public static boolean allows(Actor actor, String tenantUid, String tenantName) {
    if (actor == null || !actor.isAuthenticated() || !actor.hasRole("admin")) {
      return false;
    }
    return actor.hasScope("platform:global_access") || tenantUid.equals(actor.getTenant())
        || tenantName.equals(actor.getTenant());
  }
}
